import os,subprocess,zipfile,xml.etree.ElementTree as ET
root='workspace'
for dp,ds,fs in os.walk(root):
 for fn in sorted(fs):
  p=os.path.join(dp,fn); ext=fn.rsplit('.',1)[-1].lower()
  print('\\n###',p)
  try:
   if ext=='txt': print(open(p,encoding='utf-8').read())
   elif ext=='pdf':
    x=subprocess.run(['pdftotext','-layout',p,'-'],capture_output=True,text=True)
    print(x.stdout if x.returncode==0 else 'PDF_READ_ERROR '+x.stderr)
   elif ext=='docx':
    z=zipfile.ZipFile(p); t=ET.fromstring(z.read('word/document.xml')); ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    print('\\n'.join(''.join(x.itertext()) for x in t.findall('.//w:p',ns)))
   elif ext=='xlsx':
    x=subprocess.run(['python3','-c',\"import openpyxl,sys; w=openpyxl.load_workbook(sys.argv[1],data_only=True); [print('SHEET',s.title, *list(s.values),sep='\\\\n') for s in w]\",p],capture_output=True,text=True)
    print(x.stdout if x.returncode==0 else 'XLSX_READ_ERROR '+x.stderr)
  except Exception as e: print('READ_ERROR',repr(e))
PY"

