/bin/zsh -lc "python3 - <<'PY'
import os,zipfile,xml.etree.ElementTree as ET,re
for dp,ds,fs in os.walk('workspace'):
 for fn in sorted(fs):
  p=os.path.join(dp,fn)
  if fn.lower().endswith('.xlsx'):
   print('\\n###',p)
   try:
    z=zipfile.ZipFile(p); ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
    ss=[]
    if 'xl/sharedStrings.xml' in z.namelist():
     root=ET.fromstring(z.read('xl/sharedStrings.xml')); ss=[''.join(t.text or '' for t in si.findall('.//m:t',ns)) for si in root.findall('m:si',ns)]
    wb=ET.fromstring(z.read('xl/workbook.xml')); rel=ET.fromstring(z.read('xl/_rels/workbook.xml.rels')); rels={x.attrib['Id']:x.attrib['Target'] for x in rel}
    for sh in wb.findall('.//m:sheet',ns):
     target=rels[sh.attrib['{'+ns['r']+'}id']].lstrip('/'); target=target if target.startswith('xl/') else 'xl/'+target
     print('SHEET',sh.attrib['name'])
     root=ET.fromstring(z.read(target))
     for row in root.findall('.//m:sheetData/m:row',ns):
      vals=[]
      for c in row.findall('m:c',ns):
       v=c.find('m:v',ns); val=v.text if v is not None else ''
       if c.attrib.get('t')=='s' and val: val=ss[int(val)]
       inline=c.find('m:is',ns)
       if inline is not None: val=''.join(t.text or '' for t in inline.findall('.//m:t',ns))
       vals.append(f\"{c.attrib.get('r')}={val}\")
      print(' | '.join(vals))
   except Exception as e: print('ERROR',e)
  elif fn.lower().endswith('.pdf'):
   b=open(p,'rb').read(); print('\\n###',p)
   for s in re.findall(rb'\\((["'^()]*)'"\\)',b):
    try:
     t=s.decode('utf-8')
     if any('\\u4e00'<=c<='\\u9fff' for c in t): print(t)
    except: pass
   print('RAW_TEXT',b.decode('latin1','ignore')[:800].replace('\\n',' '))
PY"

